&reftitle.description;

 public ExceptionnullYaf_Request_Abstract::getException


Obtém a exceção capturada durante o despacho.

  &reftitle.examples;

   Exemplo de Yaf_Request_Abstract::getException


<?php
// No bootstrap, habilita a captura de exceções para que qualquer exceção
// lançada durante o despacho seja encaminhada para a ação de erro
Yaf_Dispatcher::getInstance()->catchException(true);

class ErrorController extends Yaf_Controller_Abstract
{
    public function errorAction($exception)
    {
        var_dump($this->getRequest()->getException() === $exception);
    }
}
?>

